SOURCE_CLAIM_JSON: {"title":"20th CPC National Congress concludes in Beijing, Xi Jinping presides over closing session and delivers important speech","publisher":"gov.cn / Xinhua","publication_date":"2022-10-23","url":"https://english.www.gov.cn/news/topnews/202210/23/content_WS63551debc6d0a757729e1950.html","claim":"The congress adopted a revised Party Constitution and called on the whole Party, the military, and the Chinese people to rally closely around the Party Central Committee with Xi Jinping at its core.","locator":"Opening report paragraphs and the closing-session summary","source_type":"official","source_confidence":"high","source_confidence_reason":"Contemporaneous official congress text; direct statement of party-state consolidation.","final_evidence_use":"final_evidence","period_fit":"Directly within the 2022 target period.","ruler_attribution":"Directly attributable to Xi because he presided over the closing session and the text centers his core position.","contrary_evidence":["This is intra-party consolidation, not public democratic contestability."],"lenses":["4B.5","4B.8","4B.10"]}
